import{_ as e,o as t,c as l,ae as i}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"テンプレート明細インポート（CSV）","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/01-template-bill-import-guide.md","filePath":"v1/ja/guide/01-template-bill-import-guide.md"}'),o={name:"v1/ja/guide/01-template-bill-import-guide.md"};function r(s,a,n,d,c,h){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="テンプレート明細インポート-csv" tabindex="-1">テンプレート明細インポート（CSV） <a class="header-anchor" href="#テンプレート明細インポート-csv" aria-label="Permalink to &quot;テンプレート明細インポート（CSV）&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>Koala は外部ファイルから取引明細（帳簿）をインポートできます。移行や過去データの取り込みに便利です。<br> テンプレート / WeChat / Alipay / Pixiu / iCost の 5 つの方式に対応しています。</p><h2 id="📁-対応ファイル形式" tabindex="-1">📁 対応ファイル形式 <a class="header-anchor" href="#📁-対応ファイル形式" aria-label="Permalink to &quot;📁 対応ファイル形式&quot;">​</a></h2><ul><li>CSV：テンプレート、Alipay、Pixiu</li><li>Excel：WeChat、iCost</li></ul><h2 id="🚀-インポート手順" tabindex="-1">🚀 インポート手順 <a class="header-anchor" href="#🚀-インポート手順" aria-label="Permalink to &quot;🚀 インポート手順&quot;">​</a></h2><ol><li>Koala → <strong>設定</strong> → <strong>明細インポート</strong></li><li><strong>インポート元</strong> を選択</li><li><strong>ファイルパス</strong> でファイルを選択</li><li><strong>帳本（Ledger）</strong> を選択</li><li>右上の <strong>解析</strong> → プレビュー確認 → <strong>インポート</strong></li></ol><blockquote><p>⚠️ 重要：インポート元を間違えると解析に失敗することがあります。</p></blockquote><h2 id="📝-テンプレート-csv-のポイント" tabindex="-1">📝 テンプレート CSV のポイント <a class="header-anchor" href="#📝-テンプレート-csv-のポイント" aria-label="Permalink to &quot;📝 テンプレート CSV のポイント&quot;">​</a></h2><ul><li>区切り文字：カンマ <code>,</code></li><li>日付形式：<code>yyyy/MM/dd</code>（例：2026/01/01）</li><li>1 行目はヘッダー必須</li></ul><hr><p><strong>最終更新</strong>：2026 年 1 月</p>',12)])])}const g=e(o,[["render",r]]);export{p as __pageData,g as default};
